public static void main(Args _args)
{
    Set transferredSites = new Set(Types::String);
    Set visitedSites = new Set(Types::String);
    container toVisit;

    toVisit = ["Lavertfood"];

    //ListIterator iterator = new ListIterator(toVisit);

    for (int i = 1; i<= conLen(toVisit); i++)
    {
        str currentSite = conPeek(toVisit, i);

        //toVisit.removeFirst();

        // Skip if already visited
        if (visitedSites.in(currentSite))
        continue;

        visitedSites.add(currentSite);

        METReqItemTableInventDimView metReqItemTableInventDimView;
        METItemStatusWarehouses metItemStatusWarehouses;

        while select metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == '13011'
        && metReqItemTableInventDimView.InventSiteId != currentSite
        && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
        && metReqItemTableInventDimView.MainWarehouseInventSiteId == currentSite
        notexists join metItemStatusWarehouses
        where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
        {
            if (!transferredSites.in(metReqItemTableInventDimView.InventSiteId))
            {
                transferredSites.add( metReqItemTableInventDimView.InventSiteId);
                toVisit += metReqItemTableInventDimView.InventSiteId; // Enqueue next site
            }
        }
    }
    // return transferredSites;


    SetEnumerator   setEnumerator;

    if (!transferredSites.empty())
    {
        setEnumerator = transferredSites.getEnumerator();
        setEnumerator.reset();
        while (setEnumerator.moveNext())
        {
            info(strfmt("Site: %1",setEnumerator.current()));
        }
    }
}

/// <summary>
/// Update all transfer sites
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <param name = "_status">METItemStatus</param>
public static void updateItemStatusToTransferSite(ItemId _itemId, InventSiteId _inventSiteId, METItemStatus _status)
{

    if(!_itemId || !_inventSiteId)
    {
        return;
    }
    Set transferredSites = new Set(Types::String);
    Set visitedSites = new Set(Types::String);
    container toVisit;

    toVisit = [_inventSiteId];

    for (int i = 1; i<= conLen(toVisit); i++)
    {
        str currentSite = conPeek(toVisit, i);

        // Skip if already visited
        if (visitedSites.in(currentSite))
        {
            continue;
        }

        visitedSites.add(currentSite);

        METReqItemTableInventDimView metReqItemTableInventDimView;
        METItemStatusWarehouses metItemStatusWarehouses;

        while select metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == _itemId
        && metReqItemTableInventDimView.InventSiteId != currentSite
        && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
        && metReqItemTableInventDimView.MainWarehouseInventSiteId == currentSite
        notexists join metItemStatusWarehouses
        where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
        {
            if (!transferredSites.in(metReqItemTableInventDimView.InventSiteId))
            {
                transferredSites.add( metReqItemTableInventDimView.InventSiteId);
                toVisit += metReqItemTableInventDimView.InventSiteId; // Enqueue next site

                //Activate Item status
                METInventItemOrderSetup metInventItemOrderSetup;

                select forupdate metInventItemOrderSetup
                    where metInventItemOrderSetup.RecId == metReqItemTableInventDimView.ReqItemTableRecId;

                if (metInventItemOrderSetup)
                {
                    ttsbegin;
                    metInventItemOrderSetup.ItemStatus = _status;
                    metInventItemOrderSetup.PublishPriceBook = NoYes::Yes;
                    metInventItemOrderSetup.PublishPortal = NoYes::Yes;
                    metInventItemOrderSetup.PublishHost = NoYes::Yes;
                    metInventItemOrderSetup.update();
                    ttscommit;
                }
                /*
                METChangeItemStatusController controller  = METChangeItemStatusController::construct();
                METChangeItemStatusContract contract = controller ? controller.getDataContractObject() : null;

                if (!contract)
                {
                    throw error(Error::wrongUseOfFunction(funcName()));
                }

                // Set contract fields
                contract.parmItemId(_itemId);
                contract.parmInventSiteId(metReqItemTableInventDimView.InventSiteId);
                contract.parmMETItemStatus(_status);

                //Set controller class method
                controller.parmExecutionMode(SysOperationExecutionMode::Synchronous); // Set execution mode
                controller.parmShowDialog(false);
                controller.parmLoadFromSysLastValue(false);
                //controller.parmInBatch(true);
                controller.parmDialogCaption(strFmt("%1 - %2 - %3 - %4", "@MET:ChangeItemStatus", _itemId, _inventSiteId, _status));
                controller.startOperation();
                */
            }
        }
    }
}
